Um sistema bancário realiza transferência entre contas por meio da biblioteca PDO com conexões configuradas para lançar PDOException em caso de falha:

try {
    $pdo->beginTransaction();
    $pdo->exec("UPDATE contas SET saldo = saldo - 100 WHERE id = 1");
    $pdo->exec("UPDATE contas SET saldo = saldo + 100 WHERE id = 99999"); // falha de chave estrangeira
    $pdo->commit();
} catch (PDOException $e) {
    $pdo->rollBack();
}

